<form class="filter-row" method="get"><input type="hidden" name="page" value="pelanggan"><input class="field search-field" name="q" placeholder="Cari nama atau perusahaan..." value="<?= h($_GET['q']??'') ?>"><button class="btn light">Cari</button></form><section class="panel"><div class="panel-head"><div><h2>Daftar Pelanggan</h2><p><?= count($store['pelanggan']) ?> pelanggan aktif</p></div></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Perusahaan</th><th>No. HP</th><th>Status</th></tr></thead><tbody><?php foreach($store['pelanggan'] as $p): if(!empty($_GET['q']) && stripos($p['nama'].$p['perusahaan'],(string)$_GET['q'])===false)continue; ?><tr><td><b><?= h($p['nama']) ?></b></td><td><?= h($p['perusahaan']) ?></td><td><?= h($p['telepon']) ?></td><td><?= status_badge($p['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
